function clientStartEditDependsOn() {
    var card = document.querySelector('.feature-card[data-id="' + _detailFeatureId + '"]');
    var currentDeps = [];
    try { currentDeps = JSON.parse(card.getAttribute('data-depends-on') || '[]'); } catch(e) {}

    // Build a picker showing all features from the board (excluding self)
    var allCards = document.querySelectorAll('.feature-card');
    var options = '';
    var selfBoard = card.getAttribute('data-board');
    allCards.forEach(function(c) {
        var cId = c.getAttribute('data-id');
        var cTitle = c.getAttribute('data-title');
        var cBoard = c.getAttribute('data-board');
        var cStage = c.getAttribute('data-stage');
        if (cId !== _detailFeatureId && cBoard === selfBoard) {
            var checked = currentDeps.indexOf(cId) >= 0 ? ' checked' : '';
            options += '<label style="display:block;color:#c9d1d9;font-size:0.75rem;padding:0.15rem 0;cursor:pointer">' +
                '<input type="checkbox" class="dep-checkbox" value="' + cId + '"' + checked + ' style="margin-right:0.3rem">' +
                escapeHtml(cTitle) + ' <span style="color:#8b949e">(' + cStage + ', ' + cId + ')</span></label>';
        }
    });

    document.getElementById('detail-field-depends-on').innerHTML =
        '<div style="max-height:200px;overflow-y:auto;background:#0d1117;border:1px solid #30363d;border-radius:4px;padding:0.3rem">' +
        (options || '<span style="color:#484f58">No other features on this board</span>') +
        '</div>' +
        '<div style="margin-top:0.3rem"><button onclick="saveEditDependsOn()" style="padding:0.2rem 0.5rem;border:none;border-radius:4px;cursor:pointer;font-size:0.7rem;font-weight:600;color:#fff;background:#238636">Save</button>' +
        '<button onclick="cancelEditDependsOn()" style="padding:0.2rem 0.5rem;border:none;border-radius:4px;cursor:pointer;font-size:0.7rem;color:#c9d1d9;background:#21262d;margin-left:0.3rem">Cancel</button>' +
        '<span id="edit-depends-on-feedback" style="margin-left:0.3rem;font-size:0.7rem"></span></div>';
}

function saveEditDependsOn() {
    var checkboxes = document.querySelectorAll('.dep-checkbox');
    var selected = [];
    checkboxes.forEach(function(cb) {
        if (cb.checked) selected.push(cb.value);
    });
    var feedbackEl = document.getElementById('edit-depends-on-feedback');

    fetch('/api/clients/' + encodeURIComponent(_clientID) + '/features/' + encodeURIComponent(_detailFeatureId) + '/edit-depends-on?key=' + encodeURIComponent(key), {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({depends_on: selected})
    }).then(function(resp) {
        if (resp.ok) {
            feedbackEl.textContent = 'Saved';
            feedbackEl.style.color = '#3fb950';
        } else {
            resp.json().then(function(d) {
                feedbackEl.textContent = d.error || 'Error';
                feedbackEl.style.color = '#f85149';
            });
        }
    });
}

function cancelEditDependsOn() {
    // Re-render by re-clicking the card (close and reopen detail)
    var card = document.querySelector('.feature-card[data-id="' + _detailFeatureId + '"]');
    if (card) { toggleFeatureDetail(card); toggleFeatureDetail(card); }
}
```

